function t(k) { const d = I18N[LANG] || I18N.en; const s = (k in d) ? d[k] : I18N.en[k]; return s == null ? k : s; }
function tf(k, vars) { let s = t(k); Object.keys(vars || {}).forEach(v => { s = s.split('{' + v + '}').join(vars[v]); }); return typeof fillFactVars === 'function' ? fillFactVars(s) : s; }
/* 8 Oct 2026 (D2-05): the STATIC half of applyLang() - <html lang>, every
   [data-i18n] / -ph / -title in the markup and the language buttons. It needs
   no settings or data, so it also runs once at the very end of this file
   (deferred script = the DOM is parsed) and a Nepali visitor on a slow link
   no longer reads an English shell until init() has awaited the store. */
function applyStaticLang() {
  document.documentElement.lang = LANG;
  /* 24 Sep 2026: t() returns the KEY when nothing is defined for it, so an
     element whose key was never added had its perfectly good English
     fallback markup overwritten with the developer's key name — eleven of
     them were printing "waTicketTitle", "waReqChat" and friends to real
     customers on the home page. The markup fallback is always better than a
     key, so an unknown key now leaves the element exactly as authored.
     tests/i18n-check.js still reports the gap, which is where it belongs. */
  $$('[data-i18n]').forEach(el => {
    const k = el.getAttribute('data-i18n');
    const s = t(k);
    if (s !== k) el.innerHTML = s;
  });
  $$('[data-i18n-ph]').forEach(el => { el.setAttribute('placeholder', t(el.getAttribute('data-i18n-ph'))); });
  /* 20 Sep 2026: an icon-only control (the office 📍, the mic, the sheet's
     close X) has no text to translate - its label is the title / aria-label.
     data-i18n-title was already in the markup but nothing ever read it. */
  $$('[data-i18n-title]').forEach(el => { const s = t(el.getAttribute('data-i18n-title')); el.setAttribute('title', s); el.setAttribute('aria-label', s); });
  $$('.lang-btn').forEach(b => b.classList.toggle('on', b.getAttribute('data-lang') === LANG));
  /* the phone header's language pill (19-premium.js) follows at once (D2-06) */
  if (typeof window.shgLangMiniLabel === 'function') { try { window.shgLangMiniLabel(); } catch (e) {} }
  /* site facts (9 Oct 2026, 02-config.js): refill [data-fact*] and {npr}-style placeholders */
  if (typeof hydrateFacts === 'function') { try { hydrateFacts(); } catch (e) {} }
}
function applyLang() {
  /* Redrawn at the END of this function — see the tail call below. Both
     boards are built from t()/tf(), so a language switch that skipped them
     left the fares in the previous language while everything else changed. */
  applyStaticLang();
  if (typeof updateNavUser === 'function') updateNavUser();
  /* The quick-date chips are built in JS, so [data-i18n] can't reach them. */
  if (typeof renderDateChips === 'function') renderDateChips();
  /* Same for the fare board and the live fare strip. */
  if (typeof renderFareBoard === 'function') renderFareBoard();
  if (typeof renderPricingCards === 'function') renderPricingCards();
  /* applyDirection() re-labels the town picker (Boarding vs Drop) for the
     current direction and calls renderFareLive itself; fall back to the plain
     strip before the simple-search wiring exists. */
  if (typeof applyDirection === 'function') applyDirection();
  else if (typeof renderFareLive === 'function') renderFareLive();
  /* The assistant's WhatsApp row is built in JS too. */
  if (typeof renderAiWhatsApp === 'function') renderAiWhatsApp();
  /* And the running-offer ribbon (6 Oct 2026). */
  if (typeof renderOfferRibbon === 'function') renderOfferRibbon();
  /* the tab title follows the language too (D2-M1) */
  if (typeof shgViewTitle === 'function') { try { shgViewTitle(); } catch (e) {} }
  /* site facts (9 Oct 2026): the office list re-localises, then every [data-fact*] is refilled */
  if (typeof renderOffices === 'function') { try { renderOffices(); } catch (e) {} }
  if (typeof hydrateFacts === 'function') { try { hydrateFacts(); } catch (e) {} }
}
function setLang(l) {
  if (!I18N[l]) l = 'en';
  LANG = l;
  try { localStorage.setItem('shg:lang', l); } catch (e) {}
  /* Remember it against the account too, so the choice follows the
     traveller to another device. Fire-and-forget: the language has already
     changed locally and a failed write must never block that. */
  try {
    if (typeof shgApi !== 'undefined' && shgApi && typeof shgApi.post === 'function') {
      shgApi.post('/lang.php', { lang: l }).catch(function () {});
    }
  } catch (e) {}
  applyLang();
  /* Re-render the current dynamic view — except checkout, where a
     re-render would wipe half-typed passenger details. */
  if ((location.hash || '#/').indexOf('#/checkout') !== 0) router();
}
document.addEventListener('click', (e) => {
  const b = e.target.closest('.lang-btn'); if (!b) return;
  setLang(b.getAttribute('data-lang'));
});
/* D2-05: the static translation right away - the full applyLang() (fares,
   date chips, ribbon) still runs from init() once the data is in. */
try { applyStaticLang(); } catch (e) { /* never block the bundle */ }
